        getPresets() { return null; }

        _lang() {
            var l = null;
            try {
                if (window.vcI18n && window.vcI18n._lang) l = window.vcI18n._lang;
                else if (document.documentElement.lang) l = document.documentElement.lang;
            } catch (err) { l = null; }
            l = String(l || 'en').substring(0, 2).toLowerCase();
            return l === 'es' ? 'es' : 'en';
        }

        _t(key) {
            var tr = this.getTranslations(), l = this._lang();
            return (tr[l] && tr[l][key] !== undefined) ? tr[l][key] : ((tr.en && tr.en[key]) || key);
        }

        _tf(key, vars) {
            var s = this._t(key);
            Object.keys(vars || {}).forEach(function (k) { s = s.split('{' + k + '}').join(String(vars[k])); });
            return s;
        }

        _fmt(n, dec) {
            var v = Number(n);
            if (!isFinite(v)) return '-';
            try { return v.toLocaleString(this._lang() === 'es' ? 'es-CO' : 'en-US', { minimumFractionDigits: dec, maximumFractionDigits: dec }); }
            catch (err) { return v.toFixed(dec); }
        }

