        _updateBriefing(state) {
            var p = (state && state.currentPeriod) || 1;
            var done = p > this.ROUNDS.length;
            var idx = Math.min(p - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = this._lang();
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = done ? this._t('briefing_done') : round['briefing_' + lang];
            var dataPanel = document.getElementById('dataPanelContainer');
            var dataPanelContent = document.getElementById('dataPanelContent');
            if (dataPanel && dataPanelContent && round['dataPanel_' + lang]) {
                dataPanelContent.innerHTML = round['dataPanel_' + lang];
                dataPanel.style.display = done ? 'none' : 'block';
            }
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var hist = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.history) || [];
            this._paintEvents(p > 1 && hist.length >= p - 1 ? ds.lastEventKeys : null);
            this._paintChartAlt(ds);
            for (var r = 0; r < this.ROUNDS.length; r++) {
                var controlEl = document.getElementById(this.ROUNDS[r].controls);
                if (controlEl) controlEl.style.display = (!done && r === idx) ? 'block' : 'none';
            }
        }

        _bindLanguage() {
            if (this._langBound) return;
            this._langBound = true;
            var self = this;
            var repaint = function () {
                try {
                    var st = window.mySimulation && window.mySimulation.state;
                    self._updateBriefing({ currentPeriod: (st && st.currentPeriod) || 1 });
                } catch (err) { /* repaint is best effort */ }
            };
            document.addEventListener('express:langchanged', repaint);
            try { if (window.mySimulation && window.mySimulation.eventBus) window.mySimulation.eventBus.on('language:changed', repaint); } catch (err) { /* no bus */ }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CostDecAdapter(), {
            simulationType: 'costdec_managerial_accounting',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

